import math


def add(a, b):
    # sum two numbers
    return a + b


def average(xs):
    total = 0
    for x in xs:
        total += x
    return total / len(xs)


class Stats:
    def top(self, xs):
        return sorted(xs)[-1]

    def spread(self, xs):
        return max(xs) - min(xs) + 1
